"""Generated by bh-bhengine-pyspark from a BH ENGINE pipeline.json.
Source pipeline: bh_oracle_jar_bh_env_nojar
Secrets: set *_env variables from connections.yml before running.
JDBC/S3/Kafka jars: configured via spark.jars.packages (see main() builder).
Testable: call run_pipeline(spark, conns, fixtures={...}, sinks={}) with mock rows.

Self-installing: `python main.py` installs requirements.txt on first run.
"""

from __future__ import annotations

import json
import os
from pathlib import Path

"""Standalone spark-plain runtime helpers (also inlined into generated main.py).

Kept free of any provider-specific imports so published pipelines stay runnable
without installing the migrate provider package.
"""


import importlib.util
import json
import os
import subprocess
import sys
from pathlib import Path


# Import name -> pip requirement for the driver process. JDBC/Kafka drivers are
# JVM jars handled by spark.jars.packages, so this list is connector-independent.
# Specs mirror requirements.txt so a relocated main.py installs the same versions
# (notably PySpark 3.x: the emitted code is not validated against PySpark 4).
_REQUIRED_PACKAGES = {
    "pyspark": "pyspark>=3.5,<4",
    "yaml": "pyyaml>=6.0",
    "boto3": "boto3>=1.34",
}

_BOOTSTRAPPED = "_BH_SPARK_PLAIN_BOOTSTRAPPED"
# Set by TTU (and similar hosts) when main.py is exec()'d in-process — never
# create a sibling .venv or os.execve (that would replace the host process).
_MANAGED = "BH_SPARK_PLAIN_MANAGED"


def _in_virtualenv():
    return bool(os.environ.get("VIRTUAL_ENV")) or sys.prefix != getattr(
        sys, "base_prefix", sys.prefix
    )


def _project_venv_python(base):
    """Create (once) a virtualenv beside main.py and return its interpreter."""
    venv_dir = base / ".venv"
    python = venv_dir / ("Scripts/python.exe" if os.name == "nt" else "bin/python")
    if python.is_file():
        return python
    print(f"Creating virtualenv: {venv_dir}")
    try:
        subprocess.check_call([sys.executable, "-m", "venv", str(venv_dir)])
    except (OSError, subprocess.CalledProcessError) as exc:
        raise RuntimeError(
            f"Could not create {venv_dir}: {exc}\n"
            "Install the venv module (Debian/Ubuntu: sudo apt install python3-venv), "
            "or run this pipeline from an activated virtualenv."
        ) from exc
    return python


def _packages_importable(python):
    """True when ``python`` can already import every required package."""
    probe = "import " + ", ".join(sorted(_REQUIRED_PACKAGES))
    try:
        return (
            subprocess.call(
                [str(python), "-c", probe],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )
            == 0
        )
    except OSError:
        return False


def _pip_install(python, base, modules):
    """Install requirements.txt when shipped, else the given modules' pinned specs."""
    requirements = base / "requirements.txt"
    if requirements.is_file():
        args = ["-r", str(requirements)]
    else:
        args = [_REQUIRED_PACKAGES[mod] for mod in modules]
    cmd = [str(python), "-m", "pip", "install", "--disable-pip-version-check", *args]
    print(f"Installing: {' '.join(args)}")
    if subprocess.call(cmd) != 0:
        raise RuntimeError("Dependency install failed: " + " ".join(cmd))


def _ensure_dependencies(base_dir=None):
    """Make the driver's Python packages importable, installing them if needed.

    Generated pipelines are meant to run as ``python3 main.py`` with no manual
    setup. Distro interpreters are externally managed (PEP 668) and reject
    installs, so when the current interpreter is not a virtualenv a project-local
    ``.venv`` is created beside main.py and the pipeline re-executes from it.
    """
    missing = [mod for mod in _REQUIRED_PACKAGES if importlib.util.find_spec(mod) is None]
    if not missing:
        return

    if base_dir is not None:
        base = Path(base_dir)
    else:
        # When main.py is exec()'d in tests, ``__file__`` may be absent.
        file_hint = globals().get("__file__")
        base = Path(file_hint).resolve().parent if file_hint else Path.cwd()
    if os.environ.get(_MANAGED) == "1":
        # Host runner owns the environment (TTU live/fixture). Do not bootstrap.
        raise RuntimeError(
            "Missing packages in managed environment: {}. Install on the host: {} -m pip install {}".format(
                ", ".join(missing),
                sys.executable,
                " ".join(_REQUIRED_PACKAGES[mod] for mod in missing),
            )
        )
    if os.environ.get(_BOOTSTRAPPED) == "1":
        # Already reinstalled and restarted once; a second pass means the install
        # did not take, so stop instead of re-executing forever.
        raise RuntimeError(
            "Still missing after install: {}\nInstall manually: {} -m pip install {}".format(
                ", ".join(missing),
                sys.executable,
                " ".join(_REQUIRED_PACKAGES[mod] for mod in missing),
            )
        )

    print(f"Missing required packages: {', '.join(missing)}")
    if _in_virtualenv():
        _pip_install(sys.executable, base, missing)
        importlib.invalidate_caches()
        return

    python = _project_venv_python(base)
    if not _packages_importable(python):
        # A virtualenv is isolated from the current interpreter, so install the
        # full set: a package present here (and thus not in `missing`) would
        # otherwise be skipped and still be absent after the restart.
        _pip_install(python, base, list(_REQUIRED_PACKAGES))

    script = Path(sys.argv[0]).resolve()
    print(f"Restarting pipeline with {python}")
    sys.stdout.flush()
    os.execve(
        str(python),
        [str(python), str(script), *sys.argv[1:]],
        dict(os.environ, **{_BOOTSTRAPPED: "1"}),
    )


def _env(name, default=None):
    if not name:
        return default
    return os.environ.get(str(name), default)


def _configure_local_spark_env():
    """Pin the driver to loopback when the host name resolves to 127.x.

    On WSL2 and many containers the host name maps to 127.0.1.1, so Spark
    advertises an unreachable interface and BlockManager registration fails with
    a NullPointerException. Skipped when a non-local master is configured.
    """
    master = os.environ.get("SPARK_MASTER") or os.environ.get("MASTER") or ""
    if master and not master.startswith("local"):
        return
    if os.environ.get("SPARK_LOCAL_IP"):
        return
    try:
        import socket

        if socket.gethostbyname(socket.gethostname()).startswith("127."):
            os.environ["SPARK_LOCAL_IP"] = "127.0.0.1"
    except Exception:
        os.environ["SPARK_LOCAL_IP"] = "127.0.0.1"


def _spark_extra_jars(project_dir=None):
    """Resolve custom JARs for ``spark.jars`` (customer libraries on the classpath).

    Collects paths from ``BH_SPARK_JARS`` / ``SPARK_JARS`` (comma, colon, or
    semicolon separated) and ``<project_dir>/jars/*.jar``. Missing paths are
    skipped. Returns a comma-separated list suitable for ``spark.jars``.
    """
    import re as _re

    paths = []
    raw = os.environ.get("BH_SPARK_JARS") or os.environ.get("SPARK_JARS") or ""
    for part in _re.split(r"[,:;]", str(raw)):
        text = part.strip()
        if text:
            paths.append(Path(text).expanduser())
    root = Path(project_dir) if project_dir is not None else Path.cwd()
    jars_dir = root / "jars"
    if jars_dir.is_dir():
        paths.extend(sorted(jars_dir.glob("*.jar")))
    seen = set()
    out = []
    for path in paths:
        try:
            resolved = str(path.resolve())
        except Exception:
            continue
        if resolved in seen or not Path(resolved).is_file():
            continue
        seen.add(resolved)
        out.append(resolved)
    return ",".join(out)


def _configure_scala_imain_classpath(spark, jvm, settings):
    """Put ``spark.jars`` on the Scala IMain classpath.

    ``usejavacp`` alone only sees ``java.class.path``. JARs added via
    ``spark.jars`` live on Spark's classloader and must be appended explicitly
    or ``import com.bh...`` fails inside IMain.
    """
    sep = str(jvm.java.io.File.pathSeparator)
    parts = []
    try:
        java_cp = jvm.java.lang.System.getProperty("java.class.path")
        if java_cp:
            parts.append(str(java_cp))
    except Exception:
        pass
    try:
        conf_jars = spark.sparkContext.getConf().get("spark.jars") or ""
        parts.extend(p.strip() for p in str(conf_jars).split(",") if p.strip())
    except Exception:
        pass
    try:
        sc_jars = spark.sparkContext._jsc.sc().jars()
        iterator = sc_jars.iterator()
        while iterator.hasNext():
            parts.append(str(iterator.next()))
    except Exception:
        pass
    merged = sep.join(dict.fromkeys(p for p in parts if p))
    if not merged:
        return
    try:
        settings.classpath().tryToSetFromPropertyValue(merged)
    except Exception:
        pass


def _spark_jar_packages(coords_csv):
    """Reconcile Maven coords with the jars already shipped inside PySpark.

    hadoop-aws must match the Hadoop runtime exactly (a 3.4.x jar on a Hadoop
    3.3.x build fails when s3a initialises), and Hadoop 3.3.x needs AWS SDK v1
    rather than v2. Coords whose artifact is already present are dropped so Ivy
    does not put a second, conflicting copy on the classpath.
    """
    coords = [c.strip() for c in str(coords_csv or "").split(",") if c.strip()]
    if not coords:
        return ""
    try:
        import pyspark

        jars_dir = Path(pyspark.__file__).parent / "jars"
        names = [p.name for p in jars_dir.glob("*.jar")] if jars_dir.is_dir() else []
    except Exception:
        return ",".join(coords)
    if not names:
        return ",".join(coords)

    hadoop_ver = ""
    for name in names:
        if name.startswith("hadoop-client-api-"):
            hadoop_ver = name[len("hadoop-client-api-") : -len(".jar")]
            break

    resolved = []
    for coord in coords:
        parts = coord.split(":")
        if len(parts) != 3:
            resolved.append(coord)
            continue
        group, artifact, version = parts
        if artifact == "hadoop-aws" and hadoop_ver:
            version = hadoop_ver
        if (
            group == "software.amazon.awssdk"
            and artifact == "bundle"
            and hadoop_ver.startswith("3.3.")
        ):
            group, artifact, version = "com.amazonaws", "aws-java-sdk-bundle", "1.12.262"
        prefix = artifact + "-"
        if any(n.startswith(prefix) and n[len(prefix) : len(prefix) + 1].isdigit() for n in names):
            continue
        resolved.append(f"{group}:{artifact}:{version}")
    return ",".join(resolved)


# Execution evidence: (kind, stage, rows, target, verified_objects)
_PIPELINE_EVENTS = []


def _log(msg):
    sys.stdout.write(msg + "\n")
    sys.stdout.flush()


# Targets written as files/objects, whose destination is a listable Hadoop path.
# A Kafka topic or JDBC table is not, so it can never be verified this way.
_VERIFIABLE_FORMATS = ("csv", "json", "parquet", "delta", "orc", "avro", "text")


def _verify_output_path(spark, path):
    """Count non-metadata files actually present at ``path`` via Hadoop FS.

    Returns None when the path cannot be inspected at all.
    """
    try:
        jvm = spark.sparkContext._jvm
        hconf = spark.sparkContext._jsc.hadoopConfiguration()
        hpath = jvm.org.apache.hadoop.fs.Path(str(path))
        fs = hpath.getFileSystem(hconf)
        if not fs.exists(hpath):
            return 0
        count = 0
        walker = fs.listFiles(hpath, True)
        while walker.hasNext():
            name = walker.next().getPath().getName()
            if not (name.startswith("_") or name.startswith(".")):
                count += 1
        return count
    except Exception:
        return None


def _record_read(stage, df):
    """Log how many rows a reader produced so an empty source is obvious."""
    try:
        rows = df.count()
    except Exception as exc:
        _log(f"[READ ] {stage}: row count unavailable ({type(exc).__name__})")
        return df
    _PIPELINE_EVENTS.append(("read", stage, rows, "", None))
    _log(f"[READ ] {stage}: {rows} row(s)")
    return df


def _record_write(spark, stage, df, target, fmt="", mode=""):
    """Log rows written; for file targets also verify objects really landed."""
    try:
        rows = df.count()
    except Exception:
        rows = -1
    verifiable = str(fmt).strip().lower() in _VERIFIABLE_FORMATS
    verified = (
        _verify_output_path(spark, target)
        if verifiable and str(target).strip()
        else None
    )
    _PIPELINE_EVENTS.append(("write", stage, rows, str(target), verified))
    detail = f"[{fmt}/{mode}]" if fmt or mode else ""
    suffix = "" if verified is None else f", verified {verified} file(s) at target"
    _log(f"[WRITE] {stage}: {rows} row(s) -> {target} {detail}{suffix}".rstrip())


def _pipeline_summary(pipeline_name=""):
    """Print an unambiguous execution verdict. Returns True when data landed.

    Exists because a spark-plain run that reads/writes nothing still exits 0,
    which is indistinguishable from success without an explicit statement.
    """
    writes = [e for e in _PIPELINE_EVENTS if e[0] == "write"]
    reads = [e for e in _PIPELINE_EVENTS if e[0] == "read"]
    bar = "=" * 68
    _log("\n" + bar)
    _log(f"PIPELINE EXECUTION SUMMARY{(': ' + pipeline_name) if pipeline_name else ''}")
    _log(bar)
    for _, stage, rows, _t, _v in reads:
        _log(f"  READ   {stage}: {rows} row(s)")
    if not writes:
        _log("  WRITE  (none)")
    for _, stage, rows, target, verified in writes:
        vtxt = "n/a" if verified is None else f"{verified} file(s)"
        _log(f"  WRITE  {stage}: {rows} row(s) -> {target} (verified: {vtxt})")
    _log(bar)

    problems = []
    if not writes:
        problems.append("no writer executed (nothing was written)")
    for _, stage, rows, target, verified in writes:
        if str(target).lower() == "discard":
            continue  # intentional Trash / Discard destination
        if rows == 0:
            problems.append(f"{stage} wrote 0 rows (source empty or fully filtered)")
        if verified == 0:
            problems.append(f"{stage} target has no files: {target}")

    if problems:
        _log("RESULT: FAILED - pipeline did NOT deliver data")
        for p in problems:
            _log(f"  - {p}")
        _log(bar)
        return False
    delivered = [e for e in writes if str(e[3]).lower() != "discard"]
    if delivered:
        total = sum(e[2] for e in delivered if e[2] > 0)
        _log(
            f"RESULT: SUCCESS - pipeline executed and delivered data "
            f"({len(delivered)} writer(s), {total} row(s) written)"
        )
    else:
        _log(
            "RESULT: SUCCESS - pipeline executed "
            "(all writers are Discard/Trash; no external target)"
        )
    _log(bar)
    return True


def _rename_column_ci(df, src, dst):
    """Rename src→dst with case-insensitive source match; no-op if src missing.

    When both names are present the destination is already populated (readers
    that project ``src AS dst`` make this rename a no-op), so the redundant
    source is dropped rather than allowed to overwrite the destination.
    """
    if src == dst:
        return df
    cols = list(df.columns)
    resolved = src if src in cols else next((c for c in cols if str(c).lower() == str(src).lower()), None)
    if resolved is None:
        return df
    if dst in cols and dst != resolved:
        return df.drop(resolved)
    return df.withColumnRenamed(resolved, dst)


def _normalize_secret_payload(data):
    """Flatten config blocks and normalize common Kafka / JDBC secret key aliases.

    Nested ``config`` is flattened away. Non-empty top-level keys override
    ``config`` (same precedence as ``{**cfg, **data}`` for real values). Empty
    or null top-level values do not wipe a nested ``config`` value.
    """
    if not isinstance(data, dict):
        return {}
    cfg = data.get("config")
    merged = dict(cfg) if isinstance(cfg, dict) else {}
    for key, value in data.items():
        if key == "config":
            continue
        if value not in (None, ""):
            merged[key] = value
    alias_groups = {
        "ssl_truststore_password": (
            "truststorePassword",
            "truststore_password",
            "sslTruststorePassword",
        ),
        "ssl_keystore_password": (
            "keystorePassword",
            "keystore_password",
            "sslKeystorePassword",
        ),
        "ssl_key_password": ("keyPassword", "key_password", "sslKeyPassword"),
        "bootstrap_servers": ("bootstrap.servers", "metadataBrokerList"),
        "security_protocol": ("securityProtocol", "security_protocol"),
        "sasl_mechanism": ("saslMechanism", "sasl_mechanism"),
        "sasl_username": ("username", "user"),
        "sasl_password": ("password", "pass"),
    }
    for canonical, aliases in alias_groups.items():
        if merged.get(canonical) not in (None, ""):
            continue
        for alt in aliases:
            if merged.get(alt) not in (None, ""):
                merged[canonical] = merged[alt]
                break
    return merged


_SECRET_CACHE = {}


def _secret_payload(value):
    if not isinstance(value, str) or not value.strip():
        return {}
    text = value.strip()
    if text.startswith("{"):
        try:
            data = json.loads(text)
        except Exception:
            data = None
        if isinstance(data, dict):
            return _normalize_secret_payload(data)
    return {"password": text, "aws_secret_access_key": text}


def _secret_name_candidates(secret_name):
    """Vault lookup names for a secret ref.

    Catalog stores scoped refs such as ``<kv-scope>/<secret-name>`` while the
    vault only holds the trailing segment, so the tail is tried first.
    """
    raw = str(secret_name or "").strip()
    if not raw:
        return []
    candidates = []
    for cand in (raw.rsplit("/", 1)[-1].strip(), raw, raw.replace("/", "-")):
        if cand and cand not in candidates:
            candidates.append(cand)
    return candidates


def _azure_secret_client():
    vault_url = (
        os.environ.get("AZURE_VAULT_URL")
        or os.environ.get("AZURE_KEYVAULT_URL")
        or os.environ.get("KEY_VAULT_URL")
    )
    if not vault_url:
        return None
    from azure.keyvault.secrets import SecretClient

    tenant = os.environ.get("AZURE_TENANT_ID")
    client_id = os.environ.get("AZURE_CLIENT_ID")
    client_secret = os.environ.get("AZURE_CLIENT_SECRET")
    if tenant and client_id and client_secret:
        from azure.identity import ClientSecretCredential

        credential = ClientSecretCredential(tenant, client_id, client_secret)
    else:
        from azure.identity import DefaultAzureCredential

        credential = DefaultAzureCredential()
    return SecretClient(vault_url=vault_url, credential=credential)


def _fetch_secret(conn):
    """Retrieve secret credentials dynamically using secret_name from Secrets Manager / KeyVault."""
    if not isinstance(conn, dict):
        return {}
    secret_name = str(conn.get("secret_name") or "").strip()
    if not secret_name:
        return {}
    if secret_name in _SECRET_CACHE:
        return _SECRET_CACHE[secret_name]

    candidates = _secret_name_candidates(secret_name)
    resolved = {}

    if str(os.environ.get("SECRET_MANAGER_PROVIDER") or "").lower() != "azure":
        try:
            import boto3
            region = conn.get("region_name") or conn.get("region") or os.environ.get("AWS_DEFAULT_REGION", "us-east-1")
            client = boto3.client("secretsmanager", region_name=region)
            for candidate in candidates:
                try:
                    resp = client.get_secret_value(SecretId=candidate)
                except Exception:
                    continue
                if "SecretString" in resp:
                    resolved = _secret_payload(resp["SecretString"])
                    if resolved:
                        break
        except Exception:
            pass

    if not resolved:
        try:
            client = _azure_secret_client()
            if client is not None:
                for candidate in candidates:
                    try:
                        sec = client.get_secret(candidate)
                    except Exception:
                        continue
                    if sec and sec.value:
                        resolved = _secret_payload(sec.value)
                        if resolved:
                            break
        except Exception:
            pass

    _SECRET_CACHE[secret_name] = resolved
    if not resolved:
        sys.stderr.write(
            f"WARNING: secret_name={secret_name!r} did not resolve; connection fields "
            f"(user/password/bucket) will be empty.\n"
        )
    return resolved


def _jdbc_driver(connection_type):
    return {
        "PostgreSQL": "org.postgresql.Driver",
        "Oracle": "oracle.jdbc.OracleDriver",
        "MySQL": "com.mysql.cj.jdbc.Driver",
        "MsSQL": "com.microsoft.sqlserver.jdbc.SQLServerDriver",
        "Snowflake": "net.snowflake.client.jdbc.SnowflakeDriver",
    }.get(str(connection_type or ""), "org.postgresql.Driver")


def _jdbc_split_table_ref(table):
    """Return (schema_or_None, bare_table) for JDBC metadata lookups."""
    text = str(table or "").strip()
    if not text or " " in text or "(" in text:
        return None, text
    if "." in text:
        schema, name = text.rsplit(".", 1)
        return schema.strip() or None, name.strip()
    return None, text


def _jdbc_discover_partition_column(spark, url, table, props):
    """Resolve a partition column when StreamSets left offsetColumn empty.

    Mirrors Transformer JDBC Table selection when skip-offset is on:
    primary-key column first, else first indexed numeric/datetime column.
    Falls back to first integral/timestamp Spark column if JDBC metadata is unavailable.
    """
    schema_name, bare = _jdbc_split_table_ref(table)
    props = dict(props or {})
    # 1) JDBC DatabaseMetaData primary keys / indexes
    try:
        jvm = spark._jvm
        driver = props.get("driver")
        if driver:
            jvm.java.lang.Class.forName(driver)
        conn = jvm.java.sql.DriverManager.getConnection(
            url,
            props.get("user") or props.get("username") or "",
            props.get("password") or "",
        )
        try:
            meta = conn.getMetaData()
            # Primary key
            rs = meta.getPrimaryKeys(None, schema_name, bare)
            pk_cols = []
            while rs.next():
                pk_cols.append((int(rs.getShort("KEY_SEQ")), rs.getString("COLUMN_NAME")))
            rs.close()
            if pk_cols:
                pk_cols.sort(key=lambda x: x[0])
                return str(pk_cols[0][1])
            # Indexed columns (unique indexes preferred)
            rs = meta.getIndexInfo(None, schema_name, bare, False, True)
            indexed = []
            while rs.next():
                col = rs.getString("COLUMN_NAME")
                if col:
                    indexed.append(str(col))
            rs.close()
            if indexed:
                # Prefer numeric/datetime among indexed via schema probe below.
                candidates = indexed
            else:
                candidates = []
        finally:
            conn.close()
    except Exception:
        candidates = []

    # 2) Spark schema probe — prefer indexed names, else first integral/timestamp.
    try:
        sample = spark.read.jdbc(url=url, table=table, properties=props).limit(0)
        fields = list(sample.schema.fields)
    except Exception:
        return None

    def _is_split_friendly(field):
        from pyspark.sql.types import (
            ByteType,
            DateType,
            DecimalType,
            DoubleType,
            FloatType,
            IntegerType,
            LongType,
            ShortType,
            TimestampType,
        )

        return isinstance(
            field.dataType,
            (
                ByteType,
                ShortType,
                IntegerType,
                LongType,
                FloatType,
                DoubleType,
                DecimalType,
                DateType,
                TimestampType,
            ),
        )

    by_name = {f.name: f for f in fields}
    for name in candidates:
        field = by_name.get(name)
        if field is not None and _is_split_friendly(field):
            return name
    for field in fields:
        if _is_split_friendly(field):
            return field.name
    return None


def _jdbc_partition_bounds(spark, url, table, props, partition_column):
    """Compute MIN/MAX for Spark JDBC partitionColumn bounds."""
    if not partition_column:
        return None, None
    col = str(partition_column).replace('"', "")
    # Quote identifiers lightly for common engines; bounds query is a subquery table.
    q = f'(SELECT MIN("{col}") AS lo, MAX("{col}") AS hi FROM {table}) _bh_bounds'
    try:
        row = spark.read.jdbc(url=url, table=q, properties=props).collect()[0]
        lo, hi = row[0], row[1]
        if lo is None or hi is None:
            return None, None
        return str(lo), str(hi)
    except Exception:
        # Unquoted fallback (Postgres lowercases unquoted identifiers).
        q2 = f"(SELECT MIN({col}) AS lo, MAX({col}) AS hi FROM {table}) _bh_bounds"
        try:
            row = spark.read.jdbc(url=url, table=q2, properties=props).collect()[0]
            lo, hi = row[0], row[1]
            if lo is None or hi is None:
                return None, None
            return str(lo), str(hi)
        except Exception:
            return None, None


def _jdbc_read_partitioned(
    spark,
    url,
    table,
    props,
    *,
    partition_column=None,
    lower_bound=None,
    upper_bound=None,
    num_partitions=1,
):
    """Spark JDBC read with optional parallel partitions (Transformer parity)."""
    props = dict(props or {})
    try:
        n = int(num_partitions or 1)
    except (TypeError, ValueError):
        n = 1
    if (
        n > 1
        and partition_column
        and lower_bound is not None
        and upper_bound is not None
        and str(lower_bound) != ""
        and str(upper_bound) != ""
    ):
        return spark.read.jdbc(
            url=url,
            table=table,
            column=str(partition_column),
            lowerBound=str(lower_bound),
            upperBound=str(upper_bound),
            numPartitions=n,
            properties=props,
        )
    return spark.read.jdbc(url=url, table=table, properties=props)


def _jdbc_align_to_table(spark, df, url, table, props):
    """Keep only columns that exist on the JDBC target table.

    Name-based JDBC writers ignore extra columns; Spark truncate/append
    requires every DataFrame column to exist on the table, so leftovers
    (e.g. validation flags) fail the write. If the table is missing
    (first create), return the original DataFrame.
    """
    read_props = {k: v for k, v in dict(props or {}).items() if k != "truncate"}
    try:
        table_cols = list(spark.read.jdbc(url=url, table=table, properties=read_props).columns)
    except Exception:
        return df
    keep = [c for c in table_cols if c in df.columns]
    if not keep:
        return df
    return df.select(*keep)


def _local_path(prefix, file_name):
    prefix = (prefix or "").rstrip("/")
    file_name = (file_name or "").lstrip("/")
    if not prefix:
        return file_name or "."
    if not file_name:
        return prefix
    return f"{prefix}/{file_name}"


def _s3_bucket(*candidates):
    """Prefer a concrete bucket; skip StreamSets/catalog stubs like ``bucket-name``."""
    placeholders = {
        "",
        "bucket",
        "bucket-name",
        "your-bucket",
        "<bucket>",
        "<bucket-name>",
        "${bucket}",
    }
    for cand in candidates:
        text = str(cand or "").strip()
        if text and text.lower() not in placeholders and not text.startswith("<"):
            return text
    return ""


def _s3_path(conn, file_name, prefix=""):
    sec = _fetch_secret(conn)
    # Envelope/conn first: live enrich inlines the real bucket; secrets often still
    # carry StreamSets placeholder metadata (bucket-name).
    bucket = _s3_bucket(conn.get("bucket"), sec.get("bucket"))
    base = (sec.get("file_path_prefix") or sec.get("prefix") or conn.get("file_path_prefix") or prefix or "").strip("/")
    name = (file_name or "").lstrip("/")
    parts = [p for p in (base, name) if p]
    key = "/".join(parts)
    if bucket:
        return f"s3a://{bucket}/{key}" if key else f"s3a://{bucket}"
    return key or "."


def _configure_s3(spark, conn):
    conf = spark.sparkContext._jsc.hadoopConfiguration()
    secrets = _fetch_secret(conn)
    # Catalog live enrich inlines aws_* on conn; prefer those when SM/KV is unreachable.
    key = (
        _env(conn.get("aws_access_key_id_env"))
        or secrets.get("aws_access_key_id")
        or secrets.get("access_key")
        or conn.get("aws_access_key_id")
        or conn.get("access_key")
        or os.environ.get("AWS_ACCESS_KEY_ID")
    )
    secret = (
        _env(conn.get("aws_secret_access_key_env"))
        or secrets.get("aws_secret_access_key")
        or secrets.get("secret_key")
        or conn.get("aws_secret_access_key")
        or conn.get("secret_key")
        or os.environ.get("AWS_SECRET_ACCESS_KEY")
    )
    token = (
        os.environ.get("AWS_SESSION_TOKEN")
        or secrets.get("aws_session_token")
        or conn.get("aws_session_token")
    )
    if key and secret:
        conf.set("fs.s3a.access.key", key)
        conf.set("fs.s3a.secret.key", secret)
        if token:
            conf.set("fs.s3a.aws.credentials.provider", "org.apache.hadoop.fs.s3a.TemporaryAWSCredentialsProvider")
            conf.set("fs.s3a.session.token", token)
        else:
            conf.set("fs.s3a.aws.credentials.provider", "org.apache.hadoop.fs.s3a.SimpleAWSCredentialsProvider")
    elif key:
        conf.set("fs.s3a.access.key", key)
    elif secret:
        conf.set("fs.s3a.secret.key", secret)
    else:
        conf.set("fs.s3a.aws.credentials.provider", "com.amazonaws.auth.DefaultAWSCredentialsProviderChain")
    region = (
        secrets.get("region_name")
        or secrets.get("region")
        or secrets.get("aws_region")
        or conn.get("region_name")
        or conn.get("region")
        or os.environ.get("AWS_DEFAULT_REGION")
        or os.environ.get("S3_REGION")
        or "us-east-1"
    )
    if region and "${" not in str(region):
        conf.set("fs.s3a.endpoint.region", str(region))
    endpoint = conn.get("endpoint_url") or secrets.get("endpoint_url") or secrets.get("endpoint")
    if endpoint and "${" not in str(endpoint):
        conf.set("fs.s3a.endpoint", str(endpoint))
    else:
        # A prior Scala stage may have set fs.s3a.endpoint to s3.${S3_REGION}....
        try:
            existing = conf.get("fs.s3a.endpoint")
            if existing and "${" in str(existing):
                conf.unset("fs.s3a.endpoint")
        except Exception:
            pass


def _param_el_maps(conns=None):
    """Build ``${PARAM}`` replacements from env + connection secrets (self-run)."""
    maps = {k: str(v) for k, v in os.environ.items() if v is not None}
    for conn in (conns or {}).values():
        if not isinstance(conn, dict):
            continue
        sec = _fetch_secret(conn)
        ctype = str(conn.get("connection_type") or "").lower()
        looks_s3 = ctype == "s3" or bool(sec.get("bucket") or conn.get("bucket"))
        if not looks_s3:
            continue
        def _put(key, *candidates):
            if maps.get(key):
                return
            for cand in candidates:
                if cand not in (None, ""):
                    maps[key] = str(cand)
                    return

        _put(
            "S3_ACCESS_KEY",
            sec.get("aws_access_key_id"),
            sec.get("access_key"),
            _env(conn.get("aws_access_key_id_env")),
        )
        _put(
            "S3_SECRET_KEY",
            sec.get("aws_secret_access_key"),
            sec.get("secret_key"),
            _env(conn.get("aws_secret_access_key_env")),
        )
        _put("S3_BUCKET_NAME", sec.get("bucket"), conn.get("bucket"))
        _put(
            "S3_FOLDER_NAME",
            sec.get("file_path_prefix"),
            sec.get("prefix"),
            conn.get("file_path_prefix"),
            "bh-test",
        )
        _put(
            "S3_REGION",
            sec.get("region_name"),
            sec.get("region"),
            sec.get("aws_region"),
            conn.get("region_name"),
            conn.get("region"),
            os.environ.get("AWS_DEFAULT_REGION"),
            "us-east-1",
        )
    # Sensible defaults so Scala stages never set fs.s3a.endpoint to
    # literal ``s3.${S3_REGION}.amazonaws.com`` when only env/bucket is set.
    if not maps.get("S3_REGION"):
        maps["S3_REGION"] = os.environ.get("AWS_DEFAULT_REGION") or "us-east-1"
    if not maps.get("S3_FOLDER_NAME"):
        maps["S3_FOLDER_NAME"] = "bh-test"
    return maps


def _resolve_param_el(text, conns=None):
    """Replace ``${PARAM}`` tokens using env + S3 connection secrets."""
    import re as _re

    raw = str(text or "")
    if "${" not in raw:
        return raw
    maps = _param_el_maps(conns)

    def _repl(match):
        key = match.group(1)
        val = maps.get(key)
        if val in (None, ""):
            return match.group(0)
        return str(val)

    return _re.sub(r"\$\{([A-Za-z0-9_]+)\}", _repl, raw)


def _load_connections(path):
    text = Path(path).read_text(encoding="utf-8")
    try:
        import yaml  # type: ignore
        data = yaml.safe_load(text) or {}
    except Exception:
        # Minimal YAML subset fallback (key: / nested scalars) via json if converted.
        data = {}
        current = None
        for raw in text.splitlines():
            line = raw.split("#", 1)[0].rstrip()
            if not line.strip():
                continue
            if not line.startswith(" ") and line.endswith(":"):
                current = line[:-1].strip().strip('"').strip("'")
                data[current] = {}
                continue
            if current is None or ":" not in line:
                continue
            k, v = line.strip().split(":", 1)
            v = v.strip()
            if v in {"true", "false"}:
                parsed = v == "true"
            else:
                try:
                    parsed = json.loads(v)
                except Exception:
                    parsed = v.strip('"').strip("'")
            data[current][k.strip()] = parsed
    if not isinstance(data, dict):
        return {}
    return data


# Scala IMain helpers. Inlined into main.py only when the pipeline contains a
# Scala stage (see _helpers_block). Custom classes referenced by user_code must
# be supplied via ./jars/ or BH_SPARK_JARS — no product embeds.
def _run_bh_scala(spark, *, name, user_code, inputs, skip_empty_batches=True, conns=None):
    """Run Scala ``user_code`` (inputs(i) / output) via JVM IMain.

    Prefer TTU ``Scala`` when installed; otherwise use an embedded IMain harness so
    standalone spark-plain projects stay runnable without bh-transformation-utils.

    ``user_code`` is the stage body from the ENGINE pipeline (after ``${PARAM}``
    resolution). Missing custom classes fail with a classpath hint — this product
    does not substitute demo-specific Scala for customer JARs.

    ``${PARAM}`` tokens (e.g. S3_BUCKET_NAME) are resolved from env and connection
    secrets before the Scala runs, so Hadoop conf is not poisoned with literal
    ``s3.${S3_REGION}.amazonaws.com``.
    """
    input_dfs = list(inputs or [])
    if not input_dfs:
        raise ValueError(f"Scala stage {name!r} requires at least one input DataFrame")
    if skip_empty_batches and all(df.rdd.isEmpty() for df in input_dfs):
        return input_dfs[0]

    resolved_code = _resolve_param_el(user_code, conns=conns)

    # TTU path (K8s / local TTU image).
    try:
        from bh_transformation_utils.engines.batch.pyspark.transformations.scala import (
            Scala as _BhScala,
        )

        stage = _BhScala(
            name=name,
            user_code=resolved_code,
            skip_empty_batches=False,  # empty-batch already handled above
        )
        out = stage.apply(
            [{"name": f"in_{i}", "data": df} for i, df in enumerate(input_dfs)]
        )
        return out[0]["data"]
    except ImportError:
        pass

    import uuid as _uuid

    jvm = spark._jvm
    prepared = resolved_code
    run_id = _uuid.uuid4().hex[:12]
    in_views = []
    stale_views = []
    try:
        for i, df in enumerate(input_dfs):
            view = f"__bh_scala_in_{run_id}_{i}"
            df.createOrReplaceTempView(view)
            in_views.append(view)
        inputs_expr = ", ".join(f'spark.table("{v}")' for v in in_views)
        harness = (
            "val spark = org.apache.spark.sql.SparkSession.getActiveSession.get\n"
            f"val inputs = Array({inputs_expr})\n"
            "var output: org.apache.spark.sql.DataFrame = _\n"
            f"{str(prepared).rstrip()}\n"
        )
        settings = jvm.scala.tools.nsc.Settings()
        settings.usejavacp().tryToSetFromPropertyValue("true")
        _configure_scala_imain_classpath(spark, jvm, settings)
        string_writer = jvm.java.io.StringWriter()
        print_writer = jvm.java.io.PrintWriter(string_writer, True)
        imain = jvm.scala.tools.nsc.interpreter.IMain(settings, print_writer)
        result = imain.interpret(harness)
        result_name = result.toString()
        compiler_log = string_writer.toString()
        success = result_name == "Success"
        if not success:
            try:
                success_cls = jvm.scala.tools.nsc.interpreter.Results.Success()
                success = result.equals(success_cls) or result == success_cls
            except Exception:
                pass
        if not success:
            hint = ""
            log_l = str(compiler_log).lower()
            if (
                "is not a member of package" in log_l
                or "not found: value" in log_l
                or "not found: type" in log_l
            ):
                hint = (
                    "\nHint: a custom class is unresolved. Place the JAR in "
                    "./jars/ next to main.py or set BH_SPARK_JARS=/path/to/lib.jar."
                )
            raise RuntimeError(
                f"Scala compilation/execution failed (status={result_name}).\n"
                f"Compiler output:\n{compiler_log}{hint}"
            )
        terms = imain.definedTerms()
        iterator = terms.iterator()
        jvm_df = None
        while iterator.hasNext():
            term = iterator.next()
            tname = term.toString()
            if tname == "output" or tname.startswith("result"):
                val_opt = imain.valueOfTerm(tname)
                if val_opt.isDefined():
                    cand = val_opt.get()
                    if cand is not None:
                        cls_name = cand.getClass().getName()
                        if "Dataset" in cls_name or "DataFrame" in cls_name:
                            jvm_df = cand
                            if tname == "output":
                                break
        if jvm_df is None:
            raise RuntimeError(
                "Scala user_code must assign output or define variables starting with 'result'"
            )
        out_view = f"__bh_scala_out_{run_id}"
        jvm_df.createOrReplaceTempView(out_view)
        out_df = spark.table(out_view)
        # Cut lineage while the input views still exist, then the views are safe to
        # delete. Returning a lazy plan instead lets a later action re-resolve those
        # view names against a mutated catalog and read another pipeline's data.
        try:
            out_df = out_df.localCheckpoint(eager=True)
            stale_views.extend(in_views)
            stale_views.append(out_view)
        except Exception:
            # Lineage still live: keep the views. They are run-scoped names, so
            # leaking them is far cheaper than resolving against the wrong plan.
            out_df.cache()
            out_df.count()
        return out_df
    finally:
        for view in stale_views:
            try:
                spark.catalog.dropTempView(view)
            except Exception:
                pass




_ensure_dependencies()

