        Customer_Tenant_Join = _rename_column_ci(Customer_Tenant_Join, "BASE_CURRENCY", "T_BASE_CURRENCY")
        Customer_Tenant_Join = _rename_column_ci(Customer_Tenant_Join, "REGULATOR_NAME", "T_REGULATOR_NAME")
