            user_code="import org.apache.spark.sql.functions._\n\nval inputDf = inputs(0)\n\n// ---------------------------------------------------------------\n// Validate the source columns required by downstream processors.\n// ---------------------------------------------------------------\n\nval requiredColumns = Seq(\n  \"C_CUSTOMER_ID\",\n  \"TENANT_ID\",\n  \"C_CUSTOMER_TYPE\",\n  \"C_FIRST_NAME\",\n  \"C_LAST_NAME\",\n  \"C_BUSINESS_NAME\",\n  \"C_KYC_STATUS\",\n  \"C_RISK_RATING\",\n  \"C_PEP_FLAG\",\n  \"C_RESIDENCE_COUNTRY\",\n  \"C_TAX_RESIDENCE\",\n  \"C_EMAIL_ADDRESS\",\n  \"T_COUNTRY_CODE\",\n  \"T_TENANT_TYPE\"\n)\n\nval missingColumns =\n  requiredColumns.filterNot(inputDf.columns.contains)\n\nif (missingColumns.nonEmpty) {\n  throw new IllegalArgumentException(\n    \"Scala_2 missing required columns: \" +\n      missingColumns.mkString(\", \") +\n      \". Available columns: \" +\n      inputDf.columns.mkString(\", \")\n  )\n}\n\n// ---------------------------------------------------------------\n// Build a normalized customer display name without custom Java.\n// ---------------------------------------------------------------\n\nval normalizedDisplayName =\n  when(\n    upper(\n      coalesce(\n        col(\"C_CUSTOMER_TYPE\"),\n        lit(\"\")\n      )\n    ) === \"BUSINESS\",\n    upper(\n      trim(\n        coalesce(\n          col(\"C_BUSINESS_NAME\"),\n          lit(\"UNKNOWN BUSINESS\")\n        )\n      )\n    )\n  ).otherwise(\n    upper(\n      trim(\n        concat_ws(\n          \" \",\n          coalesce(\n            col(\"C_FIRST_NAME\"),\n            lit(\"\")\n          ),\n          coalesce(\n            col(\"C_LAST_NAME\"),\n            lit(\"\")\n          )\n        )\n      )\n    )\n  )\n\n// ---------------------------------------------------------------\n// Preserve every column previously produced by BankRiskEngine.\n//\n// These are compatibility/default values. The custom Java risk\n// calculation is no longer executed.\n// ---------------------------------------------------------------\n\nval resultDf = inputDf\n\n  .withColumn(\n    \"SCALA_2_VALIDATION\",\n    lit(\"ALL_REQUIRED_COLUMNS_PRESENT\")\n  )\n\n  // Neutral score because the Java scoring engine was removed.\n  .withColumn(\n    \"JAVA_RISK_SCORE\",\n    lit(0).cast(\"integer\")\n  )\n\n  .withColumn(\n    \"JAVA_RISK_BAND\",\n    lit(\"UNKNOWN\").cast(\"string\")\n  )\n\n  .withColumn(\n    \"JAVA_RECOMMENDED_ACTION\",\n    lit(\"NOT_AVAILABLE\").cast(\"string\")\n  )\n\n  // Customer resides in a different country from the tenant.\n  .withColumn(\n    \"JAVA_CROSS_BORDER_CUSTOMER\",\n    when(\n      col(\"C_RESIDENCE_COUNTRY\").isNull ||\n      col(\"T_COUNTRY_CODE\").isNull,\n      lit(\"false\")\n    ).when(\n      upper(trim(col(\"C_RESIDENCE_COUNTRY\"))) =!=\n        upper(trim(col(\"T_COUNTRY_CODE\"))),\n      lit(\"true\")\n    ).otherwise(\n      lit(\"false\")\n    )\n  )\n\n  // Tax residence differs from residence country.\n  .withColumn(\n    \"JAVA_TAX_MISMATCH\",\n    when(\n      col(\"C_TAX_RESIDENCE\").isNull ||\n      col(\"C_RESIDENCE_COUNTRY\").isNull,\n      lit(\"false\")\n    ).when(\n      upper(trim(col(\"C_TAX_RESIDENCE\"))) =!=\n        upper(trim(col(\"C_RESIDENCE_COUNTRY\"))),\n      lit(\"true\")\n    ).otherwise(\n      lit(\"false\")\n    )\n  )\n\n  // Spark-native replacement for the Java fingerprint.\n  .withColumn(\n    \"JAVA_CUSTOMER_FINGERPRINT\",\n    sha2(\n      concat_ws(\n        \"|\",\n        coalesce(\n          col(\"TENANT_ID\").cast(\"string\"),\n          lit(\"\")\n        ),\n        coalesce(\n          col(\"C_CUSTOMER_ID\").cast(\"string\"),\n          lit(\"\")\n        ),\n        coalesce(\n          upper(trim(col(\"C_CUSTOMER_TYPE\"))),\n          lit(\"\")\n        ),\n        coalesce(\n          upper(trim(col(\"C_EMAIL_ADDRESS\"))),\n          lit(\"\")\n        )\n      ),\n      256\n    )\n  )\n\n  .withColumn(\n    \"JAVA_NORMALIZED_DISPLAY_NAME\",\n    normalizedDisplayName.cast(\"string\")\n  )\n\n  .withColumn(\n    \"JAVA_TRIGGERED_RULES\",\n    lit(\"CUSTOM_JAVA_RISK_ENGINE_REMOVED\").cast(\"string\")\n  )\n\n  .withColumn(\n    \"JAVA_LIBRARY_VERSION\",\n    lit(\"NOT_USED\").cast(\"string\")\n  )\n\noutput = resultDf",
